function select(label,id){const wrap=doc.createElement('label');wrap.textContent=label+' ';wrap.style.cssText='display:block;margin:10px 0';const s=doc.createElement('select');s.id=id;s.style.cssText='max-width:100%;padding:8px';wrap.appendChild(s);panel.appendChild(wrap);return s;}
function options(node,items){node.replaceChildren();const empty=doc.createElement('option');empty.value='';empty.textContent='Selecciona explícitamente';node.appendChild(empty);for(const [value,label]of items){const o=doc.createElement('option');o.value=value;o.textContent=label;node.appendChild(o);}}
function account(type){const a=(type==='doctor'?doctor.account():patient.getAccount());const id=a?.[type+'AccountId'];if(!token(id))throw Error('La cuenta necesita un identificador estable. Recarga el registro demo.');return id;}
