if(patient&&patient.getAccount){button('Recibir calendario y saldo del backoffice',()=>{patient.assertFresh?.();const id=account('patient'),state=patient.getState(),e=receive(storage,'patient_servicing',id,state.applicationId,state.servicingProjection);if(e.payload.patientAccountId!==id||e.payload.sourceApplicationId!==state.applicationId||e.payload.creditId!==state.demoBridgeCaseId||((state.offerAccepted||state.contractSigned)&&e.payload.offerFingerprintDigest!==digestText(w.PulzzoDemoBridge.fingerprint(state.offer||{}))))throw Error('El calendario no pertenece a este crédito.');w.PulzzoDemoBridge.saveMutation(state,()=>applyProjection(state,e,{kind:'patient_servicing',accountId:id,applicationId:state.applicationId}),()=>patient.save());patient.refresh();status.textContent='Calendario actualizado desde Cartera. Corte: '+e.generatedAt;});try{const id=account('patient');registerAccount(storage,'patient',id,id);}catch(_){} }
