button('Importar perfil de la cuenta vinculada',()=>{const p=mutateProvider(p=>{const e=receive(storage,'doctor_profile',p.doctorAccountId,p.doctorAccountId);importProfile(p,e);});status.textContent='Perfil recibido para revisión: '+p.id;});const fields=doc.createElement('fieldset');const legend=doc.createElement('legend');legend.textContent='Campos observados que se habilitarán';fields.appendChild(legend);fields.style.cssText='display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:6px;max-width:100%';const checks=[];for(const field of CORRECTION_FIELDS){const label=doc.createElement('label'),input=doc.createElement('input');input.type='checkbox';input.value=field;label.appendChild(input);label.appendChild(doc.createTextNode(' '+FIELD_LABELS[field]));fields.appendChild(label);checks.push(input);}panel.appendChild(fields);const reasonLabel=doc.createElement('label');reasonLabel.textContent='Motivo de corrección ';const reason=doc.createElement('textarea');reason.maxLength=1000;reason.style.cssText='display:block;width:100%;box-sizing:border-box';reasonLabel.appendChild(reason);panel.appendChild(reasonLabel);
