const fieldset=doc.createElement('fieldset'),legend=doc.createElement('legend');legend.textContent='Campos observados del paciente';fieldset.appendChild(legend);fieldset.style.cssText='display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:6px';const patientChecks=[];for(const key of PATIENT_CORRECTION_FIELDS){const label=doc.createElement('label'),input=doc.createElement('input');input.type='checkbox';input.value=key;label.appendChild(input);label.appendChild(doc.createTextNode(' '+key));fieldset.appendChild(label);patientChecks.push(input);}panel.appendChild(fieldset);const reasonLabel=doc.createElement('label');reasonLabel.textContent='Motivo de corrección del paciente ';const reason=doc.createElement('textarea');reason.maxLength=1000;reason.style.cssText='display:block;width:100%;box-sizing:border-box';reasonLabel.appendChild(reason);panel.appendChild(reasonLabel);
